<template><view class="page"><view class="profile-hero"><view class="avatar">{{ initials }}</view><view><text class="title">{{ user.nickname || '微信用户' }}</text><text class="muted">已通过微信身份登录</text></view></view><view class="card"><view class="row"><text>本月结余</text><text class="money">¥ {{ dashboard.balance || 0 }}</text></view><view class="split"></view><view class="row"><text>资金计划</text><text>{{ (dashboard.plans || []).length }} 个</text></view></view><view class="personality-card" @click="goPersonality"><view><text class="personality-tag">小兜芽 · 钱格测试</text><text class="personality-title">你的钱，是什么人格？</text><text>8 道题 + 真实账单，生成专属结果卡</text></view><text class="arrow">›</text></view><view class="card menu"><view class="menu-item" @click="goAssistant"><text>兜兜 AI 助手</text><text>›</text></view><view class="menu-item" @click="goCompliance"><view><text>服务与资质</text><text class="muted">备案、内容安全与反馈</text></view><text>›</text></view><view class="menu-item" @click="goPrivacy"><view><text>数据与隐私</text><text class="muted">按微信身份隔离</text></view><text>›</text></view></view><view class="logout" @click="logout">退出登录</view></view></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { api } from '../../utils/api'
const user=ref({});const dashboard=ref({});const initials=computed(()=>String(user.value.nickname||'芽').slice(0,1))
async function load(){user.value=await api('/auth/me');dashboard.value=await api('/dashboard')};onMounted(load);onShow(load)
function goAssistant(){uni.navigateTo({url:'/pages/assistant/index'})}async function logout(){try{await api('/auth/logout',{method:'POST'})}finally{uni.removeStorageSync('accessToken');uni.removeStorageSync('profile');uni.reLaunch({url:'/pages/auth/index'})}}
function goPersonality(){uni.navigateTo({url:'/pages/personality/index'})}
function goCompliance(){uni.navigateTo({url:'/pages/compliance/index'})}
function goPrivacy(){uni.navigateTo({url:'/pages/privacy/index'})}
</script><style scoped>.profile-hero{padding:28rpx 10rpx 36rpx;display:flex;align-items:center;gap:22rpx}.avatar{width:96rpx;height:96rpx;border-radius:50%;background:#CEEBC5;color:#58744e;font-size:40rpx;font-weight:700;display:flex;align-items:center;justify-content:center}.profile-hero view:last-child{display:flex;flex-direction:column;gap:10rpx}.money{font-size:36rpx;font-weight:700;color:#58744e}.split{height:1rpx;background:#edf2ea;margin:24rpx 0}.personality-card{background:linear-gradient(135deg,#dff1d9,#eff8ea);border:1rpx solid #d0e4c9;border-radius:30rpx;padding:30rpx;margin-bottom:22rpx;display:flex;justify-content:space-between;align-items:center}.personality-card view{display:flex;flex-direction:column;gap:10rpx;color:#58744e;font-size:23rpx}.personality-tag{font-size:21rpx;font-weight:700;letter-spacing:2rpx}.personality-title{font-size:34rpx;font-weight:800;color:#354831}.arrow{font-size:54rpx;color:#6e9562}.menu-item{display:flex;justify-content:space-between;padding:20rpx 0;border-bottom:1rpx solid #edf2ea;font-size:28rpx}.logout{color:#a65a4c;background:#fff0ec;border-radius:18rpx;padding:22rpx;text-align:center}</style>
